// Pupazzi sound: synthesized sound effects and music, all generated by code.
#pragma once
#include <stdint.h>
enum SoundId {
  SND_NONE = 0,
  SND_BULLET, SND_SHARD, SND_FROST, SND_FLAME, SND_LAVA, SND_ROCKET, SND_LEAP, SND_SLAM, SND_BLIZZARD, SND_ERUPT,
  SND_SPECIAL_READY, SND_JUMP, SND_LAND, SND_TRAMP, SND_BOMB_DROP, SND_EXPLODE, SND_EXPLODE_SMALL,
  SND_PICK_TALISMAN, SND_PICK_BOMB, SND_HURT, SND_DOWN, SND_REVIVE,
  SND_HIT, SND_DEFEAT, SND_SCORPION, SND_BOW, SND_SCARAB, SND_WARRIOR, SND_BOSS_ROAR, SND_JAVELIN, SND_SLASH,
  SND_CRATE_HIT, SND_CRATE_BREAK, SND_CAPSULE_HIT, SND_RESCUE, SND_HELP, SND_GATE, SND_ZONE_CLEAR, SND_WAVE, SND_STAR, SND_WIPE,
  SND_UI_MOVE, SND_UI_OK, SND_UI_BACK, SND_CARD_OPEN, SND_CARD_PICK, SND_PAUSE,
  // 0.5.1: SND_SCORPION is the scorpion raising its tail, SND_BOW the terracotta archer's shot;
  // arrow stuck in the ground near a player; fall into the Chichen Itza cenote (a life is lost)
  SND_ARROW_LAND, SND_SPLASH,
  // 0.5.1, the gladiator walks and attacks: step (also, more frequent, the charge run), raised sword
  // (warning of the slash), slash, wind-up of the shield charge, charge that ends against a wall
  SND_BOSS_STEP, SND_BOSS_SWEEP_WARN, SND_BOSS_SWEEP, SND_BOSS_RUSH, SND_BOSS_IMPACT,
  // 0.5.4, crate power-ups: VELOCITA', FURIA, INVINCIBILE, CARICA picked up; a power-up that ends
  SND_POWER_SPEED, SND_POWER_FURY, SND_POWER_INVINCIBLE, SND_POWER_CHARGE, SND_POWER_END,
  // 0.5.4, swing gates: SND_GATE is the gate that opens (it creaks), this one the gate that
  // slams shut (with the small bounce)
  SND_GATE_SHUT,
  NSOUNDS
};
// Tunes: title and menus, one for each map of the Earth (map style), the Colosseo boss, the victory.
// MUS_CHICHENITZA: the Chichen Itza tune (since 0.5.1).
enum MusicId { MUS_NONE = 0, MUS_TITLE, MUS_PIRAMIDI, MUS_CHICHENITZA, MUS_MURAGLIA, MUS_COLOSSEO, MUS_VICTORY, NMUSIC };
void audio_init(int rate);                       // once at startup (48000)
void audio_reset(void);                          // everything silent (back to the title)
void audio_play(int id, float pan, float vol);   // pan -1 left .. 1 right, vol 0..1 (distance)
void audio_music(int id);                        // changes tune with a short crossfade; the same tune continues; MUS_VICTORY plays once then silence; MUS_NONE fades out
void audio_set_volume(int music, int sfx);       // 0..10 each (10 = full)
void audio_duck(bool on);                        // pause: quieter music
void audio_render(int16_t* out, int frames);     // interleaved stereo, frames samples per channel
const char* audio_sound_name(int id);
const char* audio_music_name(int id);

// --- additions: for the core log and for tests/test_audio.cpp ---

struct AudioStats {
  int voices, voices_peak;        // sound effect voices playing now / maximum since the last reset
  int music_voices;               // music voices playing now
  unsigned plays, merged;         // accepted requests; how many merged with a voice already on
  unsigned stolen, dropped;       // stolen voices (faded out in 10 ms); dropped requests (limit full of more important sounds)
  unsigned blocks, limited;       // 64-sample blocks produced; those in which the limiter lowered the volume
  float lim_min;                  // lowest gain used by the limiter (1 = never stepped in)
  float peak;                     // output peak (1 = full scale)
  unsigned bad;                   // invalid values (NaN or infinities) found and zeroed
  float end_max;                  // highest envelope of a voice at the instant it switches off (must be 0)
  int parse_errors;               // errors in the tune texts (details in audio_music_text)
  int init_samples;               // samples synthesized by audio_init to calibrate the sound effects volume
};
void audio_get_stats(AudioStats* st);
void audio_clear_stats(void);
// Tune length in seconds; *loop_start (if not null) = point it restarts from, negative if it plays once.
float audio_music_length(int id, float* loop_start);
// Text of the tune bar by bar (chords, melody, notes outside the chord on the strong beats), with a
// summary and any reading errors. Returns the characters written.
int audio_music_text(int id, char* buf, int size);
// Redoes from scratch the calibration of all sound effects (stops the sound effects that are on), writes into
// buf the CAL_TAB table of audio.cpp and returns how many sounds differ from the one in use (0 = correct table).
int audio_calibration_table(char* buf, int size);
